// Изометрическая схема: те же координаты и зоны, что в живой Three.js-сцене.
export class FallbackPlan {
 constructor(container,zones,onSelect){this.container=container;this.zones=zones;this.onSelect=onSelect;this.view='iso';this.render();this.click=e=>{const id=e.target.closest('[data-zone]')?.dataset.zone;if(id)this.onSelect(id)};container.addEventListener('click',this.click)}
 project(x,y,z){if(this.view==='top')return [320+x*40,230+z*35];if(this.view==='side')return [320+x*40,310+z*12-y*45];return [320+(x-z)*27,225+(x+z)*14-y*36]}
 points(list){return list.map(p=>this.project(...p).join(',')).join(' ')}
 box(x,z,w,d,h,color,y=0,zone=''){let a=[x-w/2,y,z-d/2],b=[x+w/2,y,z-d/2],c=[x+w/2,y,z+d/2],e=[x-w/2,y,z+d/2];let top=[a,b,c,e].map(p=>[p[0],p[1]+h,p[2]]);return `<polygon points="${this.points([e,c,top[2],top[3]])}" fill="${color}" opacity=".65"/><polygon points="${this.points([b,c,top[2],top[1]])}" fill="${color}" opacity=".42"/><polygon ${zone?`data-zone="${zone}"`:''} points="${this.points(top)}" fill="${color}" stroke="#ffffff20" stroke-width=".8"/>`}
 render(){let s=this.box(0,0,12.8,10.2,.45,'#344056',-.6);s+=this.box(0,-5.1,12.8,.18,2.6,'#46526a');s+=this.box(-6.4,0,.18,10.2,2.6,'#35445a');for(let x=-5.2;x<5.8;x+=1.45){s+=this.box(x,-4.96,.85,.09,1.55,'#f5c77e',.7)}for(const z of this.zones){s+=this.box(z.x,z.z,z.w,z.d,.1,z.color,0,z.id)}s+=this.box(-1,-2.9,.12,3.7,1.5,'#49666d');s+=this.box(3.15,-2.9,.12,3.7,1.5,'#49666d');s+=this.box(-3.2,-1,5,.1,1,'#37465f');for(let z of [-.2,2.1])for(let x of [-4,-1.7]){s+=this.box(x,z,1.85,.85,.1,'#bd9671',.8);s+=this.box(x,z,.12,.12,.8,'#667184');for(let q of [-.65,.65])s+=this.box(x,z+q,.5,.5,.55,'#46516b')}for(let x of [-4.6,-3.1,-1.6]){s+=this.box(x,-3,1.05,.9,.1,'#a4b7d0',.8);s+=this.box(x,-2.25,.45,.45,.55,'#455878')}s+=this.box(1.3,-3,2.5,1.3,.13,'#8bb9b2',.8);s+=this.box(4.6,-3,1.3,2.7,1,'#ba8e6d');s+=this.box(3.3,3,3.8,1,1,'#7b7698');s+=this.box(3.2,1.8,1.9,.7,.4,'#ba9571');for(let x of [1.4,3.1,4.8])s+=this.box(x,-.2,1.2,1.5,1.9,'#46635f');for(let [x,z] of [[-5.7,4.2],[5.7,4.2],[5.7,-4.4]]){s+=this.box(x,z,.5,.5,.5,'#b08c69');s+=this.box(x,z,.8,.8,.8,'#578174',.5)}this.container.innerHTML=`<svg viewBox="0 0 640 440" role="img" aria-label="Изометрический план шести зон FreeSpace"><title>План FreeSpace: выберите зону или используйте кнопки под схемой</title>${s}</svg>`;this.filter(this.plan||'day');if(this.selected)this.highlight(this.selected)}
 highlight(id){this.selected=id;this.container.querySelectorAll('[data-zone]').forEach(p=>p.classList.toggle('selected',p.dataset.zone===id))}
 filter(plan){this.plan=plan;this.container.querySelectorAll('[data-zone]').forEach(p=>{const z=this.zones.find(z=>z.id===p.dataset.zone);p.style.opacity=z.plans.includes(plan)&&(plan!=='team'||['open','meeting'].includes(z.id))?'1':'.2';if(!z.free&&!z.shared)p.setAttribute('fill','#5d6674')})}
 setLight(mode){this.container.classList.toggle('day',mode==='day')}
 setView(view){this.view=view;this.render()}
 destroy(){this.container.removeEventListener('click',this.click)}
}
